// A trace generated by the current buyer against the in-process arena-kit simulator.
// Playback timing is for presentation; no browser action contacts the arena.
import raw from "./simulation.json";

export type Stage =
  | "research"
  | "rehearsal"
  | "analyst"
  | "negotiator"
  | "writer"
  | "close"
  | "debrief";
export interface SupplierState {
  price: number | null;
  ours?: number;
  status: string;
  cost: number | null;
  terms: Record<string, unknown>;
  valid: boolean;
}
export interface RunEvent {
  stage: Stage;
  title: string;
  summary: string;
  supplier: string | null;
  detail: Record<string, unknown>;
  suppliers: Record<string, SupplierState>;
  best: number | null;
}
export const replay = raw;
export const events = raw.events as unknown as RunEvent[];
// Presentation timing: emails stay visible longer than internal handoffs.
export function eventDelay(event?: RunEvent) {
  if (!event) return 800;
  if (event.detail.message || event.detail.reply || event.detail.quotes)
    return 1600;
  if (["research", "rehearsal", "close", "debrief"].includes(event.stage))
    return 1000;
  return event.stage === "negotiator" ? 650 : 400;
}
export const playbackSeconds = Math.round(
  (eventDelay() +
    events.slice(0, -1).reduce((sum, event) => sum + eventDelay(event), 0)) /
    1000,
);
export const money = (value: number) =>
  new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "EUR",
    maximumFractionDigits: 0,
  }).format(value);
export const price = (value: number) =>
  new Intl.NumberFormat("en-GB", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
  }).format(value);
export const supplierName = (id: string | null) =>
  replay.suppliers.find((s) => s.id === id)?.name ?? "Purchasing team";

// Final figures are revealed only after the close gate, never from a proposal.
export function dealOutcome(index: number) {
  if (!events.slice(0, index).some((event) => event.stage === "close"))
    return null;
  const result = replay.result;
  if (
    !result.deal ||
    typeof result.c_open !== "number" ||
    typeof result.c_deal !== "number"
  )
    return null;
  const savings = result.c_open - result.c_deal;
  return {
    supplier: supplierName(result.supplier_id),
    unitPrice: result.terms.unit_price,
    openingCost: result.c_open,
    totalCost: result.c_deal,
    savings,
    savingsPercent: result.c_open > 0 ? (savings / result.c_open) * 100 : null,
    months: result.terms.contract_months,
  };
}

export function initialStep(search: string) {
  const value = Number(new URLSearchParams(search).get("step"));
  return Number.isFinite(value)
    ? Math.max(0, Math.min(events.length, Math.floor(value)))
    : 0;
}

export interface RecordedMessage {
  subject?: string;
  body?: string;
  text?: string;
  terms?: Record<string, unknown>;
  term_sheets?: { terms: Record<string, unknown> }[];
  refs?: string[];
  claim_results?: { result: string }[];
}
export interface ThreadEntry {
  step: number;
  kind: "supplier" | "buyer" | "analysis" | "decision" | "close";
  event: RunEvent;
  message?: RecordedMessage;
}
export function threadEntries(index: number, sid: string): ThreadEntry[] {
  return events.slice(0, index).flatMap((event, i): ThreadEntry[] => {
    const step = i + 1;
    const quotes = event.detail.quotes as
      | Record<string, RecordedMessage>
      | undefined;
    if (quotes?.[sid])
      return [{ step, kind: "supplier", event, message: quotes[sid] }];
    if (event.stage === "close") return [{ step, kind: "close", event }];
    if (event.supplier !== sid) return [];
    if (event.detail.message)
      return [
        {
          step,
          kind: "buyer",
          event,
          message: event.detail.message as RecordedMessage,
        },
      ];
    if (event.detail.reply)
      return [
        {
          step,
          kind: "supplier",
          event,
          message: event.detail.reply as RecordedMessage,
        },
      ];
    if (event.stage === "negotiator")
      return [{ step, kind: "decision", event }];
    if (event.stage === "analyst") return [{ step, kind: "analysis", event }];

    return [];
  });
}
